package at.co.svc.agate.ai;

import java.util.*;

/** Evidence references are calculated from actual uploaded log lines, never generated by the LLM. */
public final class EvidenceExplorer {
    public record StepRef(String engine, String operation, String response, String status,
                          String label, int startLine, int endLine, boolean skipped) {}
    public record View(String title, String summary, String fix, String verification,
                       List<StepRef> steps, String logName, String expected, String actual) {
        public View(String title,String summary,String fix,String verification,List<StepRef> steps,String logName){this(title,summary,fix,verification,steps,logName,null,null);}
    }
    private final AgateExecutionParser parser = new AgateExecutionParser();

    public View forFinding(String log, ToolFinding finding) {
        String title = finding.engine() + " · Fehleranalyse";
        String summary = finding.summary();
        String fix = finding.recommendations().isEmpty() ? "Keine konkrete Korrektur ableitbar."
                : String.join("\n", finding.recommendations());
        return new View(title, summary, fix, "Keine AGATE-Testausführung; Korrektur nicht verifiziert.", steps(log), null);
    }
    public View forSoap(String log, DiagnosticResult result) {
        if (result.analysis().contains("PROBLEMTYP: SOAP_XPATH_NOT_FOUND")) {
            var corr = new SoapResponseCorrelation().inspect(log);
            if (corr.isPresent()) {
                var f = corr.get();
                String summary = "AGATE meldet: " + f.reason() + ". " + f.explanation();
                return new View("SOAP · XPath nicht gefunden", summary, f.action(),
                    "Lokale XML-Prüfung: " + (f.hits()<0?"nicht möglich":f.hits()+" Treffer") + ". Kein AGATE-Testlauf zur Korrektur ausgeführt.", steps(log), null);
            }
        }
        String analysis = result.analysis();
        if("URSACHE_EINGEGRENZT".equals(result.verificationStatus()) && analysis.contains("ASSERTION_VALUE_MISMATCH")) {
            var mismatch = new AssertionMismatchAnalyzer().inspect(log);
            if(mismatch.isPresent()) {
                var m = mismatch.get();
                String summary = "Der SOAP-ASSERT meldet unterschiedliche erwartete und tatsächliche Werte für den angegebenen Body-Pfad.";
                String fixText = "Testdaten und fachliche Hinweisvariante prüfen (insbesondere SPERRE_AB_OFFSET, SPERR_AKTEUR_KZ und TYP). Den Erwartungswert nicht automatisch anpassen.";
                return new View("SOAP · ASSERT-Wertabweichung", summary, fixText,
                    "Werteabweichung aus dem Log bestätigt; fachliche Ursache und Korrektur noch nicht verifiziert. Kein AGATE-Testlauf.", steps(log), null, m.expected(), m.actual());
            }
        }
        String fix = extractAfter(analysis, "KONKRETE KORREKTUR", "AGATE-TESTAUSFÜHRUNG");
        if(fix.isBlank()) fix = "Details im Diagnoseprotokoll ansehen.";
        String summary = "SOAP-/XPath-Analyse abgeschlossen. " +
              ("XPATH_LOKAL_BESTÄTIGT".equals(result.verificationStatus())
               ? "Die vorgeschlagene XPath-Korrektur wurde lokal mit Java bestätigt."
               : "Eine verifizierte XPath-Korrektur liegt nicht vor.");
        return new View("SOAP · XPath-Diagnose", summary, fix,
             result.verified() ? "AGATE-Ausführung bestätigt." : "Kein AGATE-Testlauf durchgeführt.", steps(log), null);
    }
    private static String extractAfter(String text,String start,String end) {
        int a=text.indexOf(start); if(a<0)return "";
        a=text.indexOf('\n',a); if(a<0)return "";
        int b=text.indexOf(end,a+1);return text.substring(a+1,b<0?text.length():b).strip();
    }
    public List<StepRef> steps(String log) {
        if(log==null || log.isBlank())return List.of();
        Optional<AgateExecutionParser.Failure> fail=parser.findFailure(log);
        if(fail.isEmpty())return List.of();
        var f=fail.get();
        List<AgateExecutionParser.Step> all=f.steps();
        List<StepRef> out=new ArrayList<>();
        int failedIndex=all.indexOf(f.failedStep());
        // Include the producer of the missing SQL response, its preceding COUNT/BUFFER, and the failed step.
        Set<Integer> chosen=new TreeSet<>();
        chosen.add(failedIndex);
        if("SQL".equals(f.engine()) && f.response()!=null) {
            for(int i=0;i<failedIndex;i++) {
                var s=all.get(i);
                if("SQL".equals(s.engine()) && "EXEC".equals(s.op()) && f.response().equals(s.response())) {
                    chosen.add(i);
                    for(int j=Math.max(0,i-2);j<i;j++)if("SQL".equals(all.get(j).engine()))chosen.add(j);
                }
            }
        }
        if("SOAP".equals(f.engine())) {
            // Preserve relevant preparation and service execution steps for failed SOAP assertions.
            for(int i=0;i<failedIndex;i++) {
                var s=all.get(i);
                String command=s.command()==null?"":s.command().toLowerCase(Locale.ROOT);
                if("CALL".equals(s.engine()) && (command.contains("fotoinfo") || command.contains("foto_info"))) chosen.add(i);
                if("SOAP".equals(s.engine()) && "EXEC".equals(s.op()) &&
                   (f.response()==null || f.response().equals(s.response()))) chosen.add(i);
            }
            for(int i=Math.max(0,failedIndex-2);i<failedIndex;i++) chosen.add(i);
        }
        if(chosen.size()==1)for(int i=Math.max(0,failedIndex-2);i<failedIndex;i++)chosen.add(i);
        String[] lines=log.split("\\R",-1);
        for(int i:chosen) {
            if(i<0 || i>=all.size())continue;
            var s=all.get(i);
            String status=s.skipped()?"SKIPPED":s.status()==null?"UNKNOWN":s.status();
            int start=Math.max(1,s.startLine());
            int end=Math.max(start,s.endLine());
            // Extend evidence to cover failure reason or skip explanation if it follows the finished line.
            if("FAILED".equals(status))end=Math.min(lines.length,end+7);
            String label=(s.engine()==null?"STEP":s.engine())+" "+(s.op()==null?"":s.op());
            out.add(new StepRef(s.engine(),s.op(),s.response(),status,label,start,end,s.skipped()));
        }
        return List.copyOf(out);
    }
}
